<?php
require_once 'auth.php'; require_admin(); require_once 'admin-functions.php';
$studentId=(int)($_GET['student_id']??0); if($studentId<=0){header('Location: admin-manage-merit.php');exit;}
$stmt=$conn->prepare("SELECT student_id,matric_no,full_name,programme,year_sem,status_category,merit_score FROM students WHERE student_id=? LIMIT 1"); $stmt->bind_param('i',$studentId); $stmt->execute(); $student=$stmt->get_result()->fetch_assoc(); if(!$student){header('Location: admin-manage-merit.php');exit;}
$h=$conn->prepare("SELECT j.title,j.location,j.job_date,j.allowance,a.status,COALESCE(a.paid_amount,j.allowance_amount,0) amount,a.applied_at FROM applications a JOIN jobs j ON a.job_id=j.job_id WHERE a.student_id=? ORDER BY a.applied_at DESC"); $h->bind_param('i',$studentId); $h->execute(); $history=$h->get_result()->fetch_all(MYSQLI_ASSOC); $total=0; foreach($history as $r){if($r['status']==='Completed')$total+=(float)$r['amount'];}
?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Student Detail</title><link rel="stylesheet" href="admin-style.css?v=10"></head><body><?php include 'admin-header.php'; ?><main class="page-panel"><section class="profile-card"><div class="avatar">👤</div><div><h2><?php echo e($student['full_name']); ?></h2><p>Matric No : <?php echo e($student['matric_no']); ?></p><p>Programme : <?php echo e($student['programme']); ?></p><p>Year/Sem : <?php echo e($student['year_sem']); ?></p><p>Status : <?php echo e($student['status_category']); ?></p><p>Merit : <strong><?php echo (int)$student['merit_score']; ?>%</strong></p><p>Total Earnings : <strong><?php echo e(format_rm($total)); ?></strong></p></div></section><section class="earnings"><div><h2>Work History</h2><div class="total"><?php echo e(format_rm($total)); ?></div></div><div class="earning-list"><?php if($history): foreach($history as $job): ?><article class="earning-card"><div><strong><?php echo e($job['title']); ?></strong><span><?php echo e($job['location']); ?> • <?php echo e($job['job_date']); ?></span><span><?php echo e($job['allowance']); ?> | <?php echo e(format_rm($job['amount'])); ?></span></div><span class="status <?php echo strtolower($job['status']); ?>"><?php echo e($job['status']); ?></span></article><?php endforeach; else: ?><article class="earning-card"><div><strong>No history yet</strong><span>This student has not applied for any job.</span></div></article><?php endif; ?></div></section></main></body></html>
